// ---- shared HMAC helpers (prepended to every Code node by n8n/build-workflows.mjs) ----
// Same scheme as convex/lib/hmac.ts: hex HMAC-SHA256 over `${unixSeconds}.${rawBody}`,
// 300 s replay window, constant-time compare. The secret comes from the container env
// (n8n/.env), never from this file or the exported workflow JSON.
const crypto = require("crypto");
const LENDLOOP_MAX_SKEW_SECONDS = 300;

function lendloopSecret() {
  const s = $env.N8N_SIGNING_SECRET;
  if (!s) throw new Error("N8N_SIGNING_SECRET is not set in the n8n container env");
  return s;
}

function lendloopSign(ts, rawBody) {
  return crypto.createHmac("sha256", lendloopSecret()).update(`${ts}.${rawBody}`).digest("hex");
}

function lendloopVerify(rawBody, tsHeader, sigHeader, nowSeconds = Math.floor(Date.now() / 1000)) {
  if (!tsHeader || !sigHeader) return { ok: false, reason: "missing headers" };
  const ts = Number(tsHeader);
  if (!Number.isInteger(ts)) return { ok: false, reason: "bad timestamp" };
  if (Math.abs(nowSeconds - ts) > LENDLOOP_MAX_SKEW_SECONDS) return { ok: false, reason: "stale timestamp" };
  const expected = Buffer.from(lendloopSign(ts, rawBody), "utf8");
  const given = Buffer.from(String(sigHeader).trim().toLowerCase(), "utf8");
  if (expected.length !== given.length) return { ok: false, reason: "bad signature" };
  return crypto.timingSafeEqual(expected, given) ? { ok: true } : { ok: false, reason: "bad signature" };
}

/** Headers + exact body for a signed POST to Convex; the HTTP Request node sends `body` raw. */
function lendloopSignedRequest(path, payload) {
  const body = JSON.stringify(payload);
  const ts = Math.floor(Date.now() / 1000);
  const base = ($env.LENDLOOP_CONVEX_SITE_URL || "").replace(/\/+$/, "");
  if (!base) throw new Error("LENDLOOP_CONVEX_SITE_URL is not set in the n8n container env");
  return { url: `${base}${path}`, body, timestamp: String(ts), signature: lendloopSign(ts, body) };
}
// ---- end shared helpers ----

// Workflow 1, step 1: verify the Convex signature over the RAW request body, refuse
// replays, and drop duplicate deliveries (Convex retries with the same event id).
const item = $input.first();
const headers = item.json.headers || {};

// The Webhook node keeps the raw body as binary "data" (option Raw Body). Re-serialising
// the parsed JSON could change bytes and break the signature, so no raw body = reject.
let raw = null;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, "data")).toString("utf8");
}
if (raw === null) return [{ json: { valid: false, reason: "raw body unavailable" } }];

const check = lendloopVerify(raw, headers["x-lendloop-timestamp"], headers["x-lendloop-signature"]);
if (!check.ok) return [{ json: { valid: false, reason: check.reason } }];

let event;
try {
  event = JSON.parse(raw);
} catch (e) {
  return [{ json: { valid: false, reason: "invalid JSON" } }];
}
if (!event || typeof event.eventId !== "string" || !event.recipient || !event.recipient.email) {
  return [{ json: { valid: false, reason: "missing fields" } }];
}

// Idempotency: remember event ids for 7 days (workflow static data persists across
// production executions). A retry that lands after a slow success is acknowledged, not re-sent.
const store = $getWorkflowStaticData("global");
store.seenEventIds = store.seenEventIds || {};
const now = Date.now();
for (const [id, at] of Object.entries(store.seenEventIds)) {
  if (now - at > 7 * 24 * 3600 * 1000) delete store.seenEventIds[id];
}
const duplicate = Boolean(store.seenEventIds[event.eventId]);
if (!duplicate) store.seenEventIds[event.eventId] = now;

return [{ json: { valid: true, duplicate, event } }];

// Workflow 1, step 2: notify the one person the event concerns. This is the logged mock
// the brief allows; swap this node for Send Email / Slack / Discord in production. It
// only ever sees the fields Convex chose to send (first name, email, tool, dates).
const SUBJECTS = {
  "loan.requested": (e) => `New request to borrow your ${e.toolName} (${e.startDate} to ${e.endDate})`,
  "loan.approved": (e) => `Approved: you can borrow the ${e.toolName} from ${e.startDate} to ${e.endDate}`,
  "loan.declined": (e) => `Declined: your request for the ${e.toolName} was not approved`,
  "loan.returned": (e) => `Marked returned: ${e.toolName}. Thanks for lending responsibly`,
};

return $input.all().map((item) => {
  const { event, duplicate } = item.json;
  if (duplicate) return { json: { eventId: event.eventId, notified: false, reason: "duplicate delivery" } };
  const subject = (SUBJECTS[event.type] || ((e) => `LendLoop update on ${e.toolName}`))(event);
  const message = {
    channel: "mock-email",
    to: event.recipient.email,
    subject,
    text: `Hi ${event.recipient.firstName}, ${subject}.`,
  };
  console.log(`[lendloop] notify ${event.type} ${event.eventId} -> ${message.to}: ${subject}`);
  return { json: { eventId: event.eventId, notified: true, message } };
});
